 99|         }
100|         if (ability2.canDealDamage(elapsedTimeSeconds)) {
101|             int damage = static_cast<int>(ability2.damagePerTick);
102|             if (damage > 0) {
103|                 dummy.takeDamage(damage);
104|             }
105|             // Update the last damage time
106|             ability2.lastDamageTime = elapsedTimeSeconds;
107|         }
108| 
